package io.github.isidorotrevino.planner.postgres;
import org.junit.jupiter.api.*;
import java.sql.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static io.github.isidorotrevino.planner.postgres.DeliveryStoreTest.*;
/** SQL owner proofs are synthetic; signatures and actual stop belong to Compose. */
class RecoveryStoreTest {
 MultiCheckpointStoreTest m;DeliveryStoreTest f;UUID delivery,receiver=id();
 @BeforeEach void setup(TestInfo info)throws Exception{m=new MultiCheckpointStoreTest();m.setup(info);f=m.f;delivery=m.delivery;String before;try(var c=f.owner()){before=m.state(c);}assertEquals(2,migrations(f.db,"26").migrate().migrationsExecuted);migrations(f.db,"26").validate();try(var c=f.owner()){assertEquals(before,m.state(c));value(c,"SELECT d4.lab_authorize(?,?,?,?)::text",id(),f.worker,delivery,receiver);}}
 @AfterEach void cleanup()throws Exception{if(f!=null)f.cleanup();}
 void expire()throws Exception{try(var c=f.owner()){sql(c,"UPDATE operation_leases SET expires_at=clock_timestamp()-interval '1 second'");m.call(c,"lab_admin",id(),delivery,"EXPIRE",null);}}
 void receipt(String step,String status)throws Exception{try(var c=f.owner()){sql(c,"INSERT INTO d2.effect_receipts(operation_id,generation,effect_key,status,evidence_ref) SELECT id,lease_generation,id||'/'||context_pack_sha256||'/'||?,?,'synthetic-observation' FROM operations WHERE id=?",step,status,f.operation);}}
 String proof(boolean terminal)throws Exception{try(var c=f.owner()){
  var rr=new TreeMap<String,Object>();for(int n=m.generation;n<=3;n++)rr.put("step-"+n,Map.of("status",terminal||n==m.generation?"APPLIED":"ABSENT","generation",m.generation,"closed",true,"payloadHash",String.valueOf(n).repeat(64)));
  return value(c,"SELECT (i||jsonb_build_object('schema','d4.recovery.proof.v1','process_stopped',true,'artifact_valid',true,'receiver_closed',true,'close_sequence',10,'host_observation_hash',repeat('a',64),'stdout_hash',repeat('b',64),'stderr_hash',repeat('c',64),'receipts',?::jsonb,'receiver_seal',jsonb_build_object('receiverId',?::uuid,'sequence',10,'steps',?::jsonb,'identity',jsonb_build_object('operation',i->'operation','attempt',i->'attempt','worker',i->'worker','resource',i->'resource','generation',i->'generation'))))::text FROM (SELECT d4.recovery_info(?) i) x",Json.write(rr),receiver,Json.write(rr),delivery);
 }}
 UUID record(boolean terminal)throws Exception{var pid=id();try(var c=f.owner()){value(c,"SELECT d4.recovery_record(?,?,?::jsonb)::text",pid,delivery,proof(terminal));}return pid;}
 UUID settle(UUID pid)throws Exception{var cid=id();try(var c=f.owner()){m.call(c,"recovery_settle",cid,pid,m.version(c));}return cid;}
 @Test void partialMonotonicResolutionContinuesSameOperationAndReservation()throws Exception{receipt("step-1","UNKNOWN");receipt("step-1","ABSENT");receipt("step-1","APPLIED");expire();var cp=settle(record(false));m.balance("0","4","0","1");try(var c=f.owner()){assertEquals("3",value(c,"SELECT count(*) FROM d2.effect_receipts"));assertEquals("true",value(c,"SELECT d4.recovery_current(?)::text",cp));}m.next(cp);m.balance("10","4","6","1");var cp2=m.commit();m.next(cp2);m.callback();try(var c=f.owner()){value(c,"SELECT d4.multi_accept(?,?,?::jsonb)::text",id(),m.delivery,m.proof(c,true));m.call(c,"multi_finalize",id(),m.delivery);assertEquals("COMPLETED",value(c,"SELECT state FROM operations"));assertEquals("1",value(c,"SELECT count(*) FROM d2.reservations"));assertEquals("3",value(c,"SELECT count(*) FROM execution_attempts"));}m.balance("0","10","0","6");}
 @Test void terminalRecoveryRequiresSeparateAcceptance()throws Exception{receipt("step-1","UNKNOWN");expire();var sid=settle(record(true));m.balance("0","10","0","6");try(var c=f.owner()){assertEquals("VERIFYING",value(c,"SELECT state FROM operations"));assertEquals("0",value(c,"SELECT count(*) FROM execution_evidence"));var cid=id();assertEquals(m.call(c,"recovery_accept",cid,sid),m.call(c,"recovery_accept",cid,sid));assertEquals("COMPLETED",value(c,"SELECT state FROM operations"));assertEquals("0",value(c,"SELECT count(*) FROM operation_leases"));assertEquals("1",value(c,"SELECT count(*) FROM execution_attempts"));assertEquals("1",value(c,"SELECT count(*) FROM execution_evidence"));assertEquals("true",value(c,"SELECT d4.worker_execution_status(?,?)->>'retirable'",f.worker,delivery));}}
 @Test void newReceiptAfterIngressRejectsSettlementAtomically()throws Exception{expire();var pid=record(false);receipt("step-2","UNKNOWN");try(var c=f.owner()){m.reject("23514",()->m.call(c,"recovery_settle",id(),pid,m.version(c)));assertEquals("RECONCILING",value(c,"SELECT state FROM operations"));}m.balance("10","0","6","0");}
 @Test void newReceiptAfterSettlementBlocksAuthorization()throws Exception{expire();var cp=settle(record(false));receipt("step-2","UNKNOWN");try(var c=f.owner()){assertEquals("false",value(c,"SELECT d4.recovery_current(?)::text",cp));m.reject("23514",()->m.call(c,"multi_authorize",id(),cp,m.version(c),"must remain blocked"));}}
 @Test void appliedCannotBeReclassifiedAbsent()throws Exception{receipt("step-2","APPLIED");expire();try(var c=f.owner()){m.reject("23514",()->record(false));}m.balance("10","0","6","0");}
 @Test void unknownOrWrongReceiverProofCannotEnter()throws Exception{expire();String p=proof(false);try(var c=f.owner()){for(var expr:List.of("jsonb_set(?::jsonb,'{receipts,step-2,status}','\"UNKNOWN\"')","jsonb_set(?::jsonb,'{receiver_seal,receiverId}',to_jsonb(gen_random_uuid()))","jsonb_set(?::jsonb,'{process_stopped}','false')","jsonb_set(?::jsonb,'{receipts,step-1,payloadHash}','\"wrong\"')")){var bad=value(c,"SELECT ("+expr+")::text",p);m.reject("23514",()->value(c,"SELECT d4.recovery_record(?,?,?::jsonb)::text",id(),delivery,bad));}}m.balance("10","0","6","0");}
 @Test void liveLeaseCannotUseRecovery()throws Exception{m.reject("23514",()->record(false));m.balance("10","0","6","0");}
 @Test void proofAndSettlementReplaysAreStableButChangedBodyConflicts()throws Exception{expire();var p=proof(false);var pid=id();try(var c=f.owner()){assertEquals(value(c,"SELECT d4.recovery_record(?,?,?::jsonb)::text",pid,delivery,p),value(c,"SELECT d4.recovery_record(?,?,?::jsonb)::text",pid,delivery,p));var cid=id();long v=m.version(c);assertEquals(m.call(c,"recovery_settle",cid,pid,v),m.call(c,"recovery_settle",cid,pid,v));m.reject("23514",()->m.call(c,"recovery_settle",cid,pid,v+1));}}
 @Test void factsImmutableAndRuntimeCannotMintResolution()throws Exception{expire();record(false);try(var c=f.owner()){m.reject("55000",()->sql(c,"UPDATE d4.recovery_proofs SET proof=proof"));sql(c,"CREATE ROLE recovery_runtime NOLOGIN;GRANT USAGE ON SCHEMA d4 TO recovery_runtime;SET ROLE recovery_runtime");m.reject("42501",()->value(c,"SELECT d4.recovery_record(NULL,NULL,'{}')::text"));m.reject("42501",()->sql(c,"SELECT * FROM d4.recovery_proofs"));}}
 @Test void blockedApprovalReturnsThroughReconciliationBeforeCheckpoint()throws Exception{expire();try(var c=f.owner()){sql(c,"UPDATE operations SET state='BLOCKED_APPROVAL',row_version=row_version+1");}settle(record(false));try(var c=f.owner()){assertEquals("CANCELLED",value(c,"SELECT state FROM operations"));assertEquals("0",value(c,"SELECT count(*) FROM execution_evidence"));}m.balance("0","4","0","1");}
 @Test void terminalNewReceiptBlocksAcceptance()throws Exception{expire();var sid=settle(record(true));receipt("step-1","UNKNOWN");try(var c=f.owner()){m.reject("23514",()->m.call(c,"recovery_accept",id(),sid));assertEquals("VERIFYING",value(c,"SELECT state FROM operations"));assertEquals("1",value(c,"SELECT count(*) FROM operation_leases"));}}

 @Test void terminalCallbackAlreadySettledIsNotConsumedTwice()throws Exception{try(var c=f.owner()){f.call(c,"worker_execution",id(),f.worker,Map.of("action","CALLBACK","delivery_id",delivery,"payload",Map.of("entries",List.of(Map.of("account_id",f.account,"settled",10,"consumed",10),Map.of("account_id",m.b,"settled",6,"consumed",6)))));}expire();var sid=settle(record(true));m.balance("0","10","0","6");try(var c=f.owner()){m.call(c,"recovery_accept",id(),sid);assertEquals("10/6",value(c,"SELECT sum(consumption_delta) FILTER(WHERE account_id=?)::int||'/'||sum(consumption_delta) FILTER(WHERE account_id=?)::int FROM d2.journal",f.account,m.b));}}
 @Test void oldGenerationCallbackIsFencedAfterRecovery()throws Exception{expire();var cp=settle(record(false));m.next(cp);try(var c=f.owner()){m.reject("23514",()->f.call(c,"worker_execution",id(),f.worker,Map.of("action","CALLBACK","delivery_id",delivery,"payload",Map.of("entries",List.of()))));}m.balance("10","4","6","1");}
 @Test void exhaustedAttemptsBlockPartialButAllowTerminalRecovery()throws Exception{expire();m.reject("23514",()->record(false));var sid=settle(record(true));try(var c=f.owner()){m.call(c,"recovery_accept",id(),sid);assertEquals("1",value(c,"SELECT count(*) FROM execution_attempts"));}}
 @Test void frozenAccountCannotBeEditedDuringRecovery()throws Exception{expire();try(var c=f.owner()){m.reject("55000",()->sql(c,"UPDATE d2.accounts SET window_end=clock_timestamp()-interval '1 second' WHERE id=?",m.b));record(false);}m.balance("10","0","6","0");}
 @Test void newResolutionAfterCaptureInvalidatesPublication()throws Exception{expire();var cp=settle(record(false));m.authorize(cp);var store=new ContinuationPlanningStore();try(var c=f.owner()){store.observeEligibility(c,id());var capture=store.capture(c,id());var result=new io.github.isidorotrevino.planner.scheduler.CapacityScheduler().plan(capture.request(),capture.snapshot());sql(c,"INSERT INTO d4.recovery_proofs SELECT ?,delivery_id,proof,evaluation,receipt_basis FROM d4.recovery_proofs LIMIT 1",id());m.reject("40001",()->store.publish(c,id(),id(),capture,result));}}
 @Test void newReceiptAfterCaptureBlocksClaim()throws Exception{expire();var cp=settle(record(false));m.authorize(cp);m.replan();receipt("step-3","UNKNOWN");try(var c=f.owner()){assertThrows(SQLException.class,()->m.launch());assertEquals("1",value(c,"SELECT count(*) FROM execution_attempts"));}m.balance("0","4","0","1");}
 @Test void failedAcceptanceNeverCompletesTerminalRecovery()throws Exception{expire();var sid=settle(record(true));try(var c=f.owner()){var artifact=insert(c,"INSERT INTO artifacts(artifact_ref,sha256,media_type,byte_size) VALUES('failure',repeat('a',64),'text/plain',1)");sql(c,"INSERT INTO execution_evidence(attempt_id,artifact_id,evidence_type) SELECT id,?,'ACCEPTANCE_FAIL' FROM execution_attempts",artifact);m.reject("23514",()->m.call(c,"recovery_accept",id(),sid));assertEquals("VERIFYING",value(c,"SELECT state FROM operations"));}}
 @Test void wrongProofReplayOwnershipIsDenied()throws Exception{expire();var pid=record(false);try(var c=f.owner()){m.reject("23514",()->m.call(c,"recovery_status",pid,id(),id()));}}
}
